input.newString:
private: {
    controlMode: 0,
    showPanel: false,
    activated: false,
    deviceCode: ''
  },

  onInit() {
    var self = this
    storage.get({
      key: 'controlMode',
      success: function(data) {
        self.controlMode = parseInt(data) || 0
      }
    })
    storage.get({
      key: 'activated',
      success: function(data) {
        self.activated = data === '1'
      }
    })
    storage.get({
      key: 'deviceCode',
      success: function(data) {
        if (data && /^\d{6}$/.test(data)) {
          self.deviceCode = data
        } else {
          self.deviceCode = self.genDeviceCode()
        }
      }
    })
  },

  genDeviceCode() {
    var code = String(Math.floor(100000 + Math.random() * 900000))
    storage.set({ key: 'deviceCode', data: code })
    return code
  },

  go() {
    if (this.activated) {
      router.push({
        uri: "/pages/level",
        params: { controlMode: this.controlMode }
      })
    } else {
      this.goActivate()
    }
  },

  goActivate() {
    router.push({ uri: "/pages/detail" })
  },

