Build mode active. Implement:

1. manifest.json — add system.device + system.file features
2. util/license.js — rewrite: deriveCode (FNV-1a), loadDeviceCode (device→storage→file→random+双写), makeActivationCode (new confirmed algorithm), checkActivation, genDeviceCode fallback
3. app.ux — call loadDeviceCode once at startup
4. index/detail/input — use new util API (they already call loadDeviceCode(storage, cb) — signature changes to loadDeviceCode(cb); and storage import may still be needed for other things)

Let me check current usages:
- index.ux: `import { loadDeviceCode } from "../../util/license"` — used as `loadDeviceCode(storage, function(code){...})`. Will change to `loadDeviceCode(function(code){...})`. index still uses storage for controlMode/activated. Keep storage import.
- detail.ux: `import { loadDeviceCode } from "../../util/license"` — `loadDeviceCode(storage, cb)`. Change signature.
- input.ux: imports `{ checkActivation }` — unchanged usage.
- app.ux: currently has its own inline generation. Change to use util loadDeviceCode.

Write util/license.js:

```js
import device from "@system.device"
import file from "@system.file"
import storage from "@system.storage"

var FILE_URI = 'internal://files/devicecode.txt'

export function deriveCode(deviceId) {
  var h = 2166136261
  var s = String(deviceId || '')
  for (var i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = (h * 16777619) >>> 0
  }
  return String(100000 + (h % 900000))
}

export function genDeviceCode() {
  return String(Math.floor(100000 + Math.random() * 900000))
}

function persistCode(code) {
  storage.set({ key: 'deviceCode', data: code })
  file.writeText({ uri: FILE_URI, text: code, fail: function() {} })
}

export function loadDeviceCode(cb) {
  var called = false
  function done(code) {
    if (called) return
    called = true
    cb(code)
  }
  device.getDeviceId({
    success: function(data) {
      if (data && data.deviceId) {
        done(deriveCode(data.deviceId))
      } else {
        loadFallback(done)
      }
    },
    fail: function() {
      loadFallback(done)
    }
  })
}

function loadFallback(done) {
  storage.get({
    key: 'deviceCode',
    success: function(data) {
      if (data && /^\d{6}$/.test(String(data))) {
        done(String(data))
      } else {
        readFile(done)
      }
    },
    fail: function() {
      readFile(done)
    }
  })
}

function readFile(done) {
  file.readText({
    uri: FILE_URI,
    success: function(data) {
      if (data && data.text && /^\d{6}$/.test(String(data.text))) {
        done(String(data.text))
      } else {
        createNew(done)
      }
    },
    fail: function() {
      createNew(done)
    }
  })
}

function createNew(done) {
  var code = genDeviceCode()
  persistCode(code)
  done(code)
}
```

Wait — potential issue: does `@system.file` have readText? Docs mention writeText, writeArrayBuffer, readText (implied), access, delete, mkdir, rmdir... The search result highlighted writeText/writeArrayBuffer/access/mkdir. readText should exist (standard quickapp file API has readText). I'll assume yes; if missing at runtime, fallback via fail callback → createNew (would regenerate, but that's only in the no-deviceId edge case). Hmm — but if readText doesn't exist, calling it throws synchronously → uncaught. To be safe wrap in try/catch:

```js
function readFile(done) {
  try {
    file.readText({...})
  } catch (e) {
    createNew(done)
  }
}
```

Also persistCode: file.writeText fail ignored. Also wrapping in try/catch for safety:

```js
function persistCode(code) {
  storage.set({ key: 'deviceCode', data: code })
  try { file.writeText({ uri: FILE_URI, text: code, fail: function() {} }) } catch (e) {}
}
```

Also note: device.getDeviceId needs the feature declared; even if the API doesn't exist on some platform, `import device` always resolves (module exists), calling getDeviceId might throw synchronously → wrap in try/catch too:

```js
try {
  device.getDeviceId({...})
} catch (e) {
  loadFallback(done)
}
```

Now makeActivationCode / checkActivation:

```js
export function makeActivationCode(dev) {
  var s = String(dev || '')
  var mid = ''
  for (var i = 0; i < s.length; i++) {
    mid += String(parseInt(s.charAt(i), 10) + 3)
  }
  var n = parseInt(mid, 10) || 0
  return ('000000' + (n + 888888)).slice(-6)
}

export function checkActivation(dev, input) {
  var s = String(input || '').trim()
  if (!/^\d{6}$/.test(s)) return false
  return s === makeActivationCode(dev)
}
```

Note: '000000' + (n+888888) — number concatenation → string, slice(-6). For n=0 → '000000888888' → '888888'. Edge if dev invalid: mid='' → parseInt→NaN → ||0 → 0 → 888888. checkActivation would compute '888888'... For input '888888' on bad dev — dev comes from our code, always 6 digits. Fine.

Hmm wait — one more check: slice on numbers as strings: (n+888888) always a number string; pad '000000' prefix; slice(-6) gives correct zero-padded last-6. ✓

